/**
 * Brings a deleted workspace back during its grace period. Takes a bare
 * `userId`: no `Actor` can be resolved for a deleted workspace, so the
 * membership is looked up here directly.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
