  }

  if (!isArchived(org)) return org;

  const deletedAt = Date.parse(org.archivedAt as string);
  if (Date.now() >= deletedAt + DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY) {
    throw new NotFoundError("Organization", orgId);
  }

  const actor: Actor = { userId, orgId: org.id, role: member.role };
  assertCan(actor, "org:restore", orgResource(org.id));

  const restored = await orgRepo.restoreOrg(org.id);

  await emit("organization.restored", {
    ...envelope(restored.id, userId),
    slug: restored.slug,
  });

  return restored;
}''')
